import {queryArchive,manilaToUTC,toManilaInput,toCSV,DICTIONARY} from '../public-data.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let archive,result,page=0,dirty=false;const pageSize=12;
const local=iso=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(iso));
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setDownloads(){for(const id of ['csv','json','metadata'])$('#'+id).disabled=dirty||!result?.rows.length;}
function markDirty(){dirty=true;$('#stale-message').hidden=false;setDownloads();countSelected();}
function countSelected(){$('#selected-count').textContent=`${document.querySelectorAll('[name=site]:checked').length} selected`;}
function sampleRange(){$('#from').value=toManilaInput(Date.parse(archive.coverage_start_utc));$('#to').value=toManilaInput(Date.parse(archive.coverage_end_utc));}
function renderPage(){const rows=result.rows.slice(page*pageSize,(page+1)*pageSize);$('#data-rows').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${local(r.period_start_utc)}–${local(r.period_end_utc)}</strong><small>${esc(toManilaInput(Date.parse(r.period_start_utc)).slice(0,10))}</small></td><td><strong>${esc(r.intersection_name)}</strong><small>${esc(r.intersection_id)} · ${esc(r.lane_id)}</small></td><td><span class="boundary ${r.flow}">${r.flow==='inbound'?'Incoming · 60 m':'Outgoing · exit'}</span></td><td>${r.vehicle_count===null?'—':r.vehicle_count.toLocaleString()}</td><td>${(100*r.observed_seconds/r.expected_seconds).toFixed(0)}%<small>${esc(r.quality)}</small></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No published data in this range.<br><small>Use the sample range to explore the demonstration archive.</small></td></tr>';
 $('#pagination').textContent=result.rows.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,result.rows.length)} of ${result.rows.length.toLocaleString()} rows`:'0 rows';$('#previous').disabled=page===0;$('#next').disabled=(page+1)*pageSize>=result.rows.length;}
function preview(){try{
 const siteIds=[...document.querySelectorAll('[name=site]:checked')].map(x=>x.value);
 result=queryArchive(archive,{siteIds,start:manilaToUTC($('#from').value),end:manilaToUTC($('#to').value),minutes:Number($('#interval').value)});page=0;dirty=false;
 $('#form-error').hidden=true;$('#stale-message').hidden=true;
 const m=result.metadata;$('#result-title').textContent=`${siteIds.length} intersection${siteIds.length===1?'':'s'} selected`;$('#result-subtitle').textContent=`${$('#from').value.replace('T',' ')} → ${$('#to').value.replace('T',' ')} · Philippine time`;
 $('#quality-tag').textContent=m.coverage_percent===100?'Complete sample coverage':m.coverage_percent===0?'No coverage':'Partial coverage';
 const sums=flow=>{const complete=result.rows.filter(r=>r.flow===flow&&r.quality==='complete');return complete.length?complete.reduce((s,r)=>s+r.vehicle_count,0):'—';};
 const incomplete=result.rows.some(r=>r.quality!=='complete');
 $('#metrics').innerHTML=[['Incoming passages',sums('inbound'),incomplete?'Complete groups only':'60 m boundary only'],['Outgoing passages',sums('outbound'),incomplete?'Complete groups only':'One exit counter per lane'],['Archive coverage',m.coverage_percent.toFixed(1)+'%','Of requested lane-time']].map(([label,value,note])=>`<div class="metric"><span>${label}</span><strong>${typeof value==='number'?value.toLocaleString():value}</strong><small>${note}</small></div>`).join('');
 $('#table-caption').textContent=`${$('#interval').value}-minute groups · synthetic source · counts in vehicles`;
 $('#quality-message').hidden=m.coverage_percent===100;$('#quality-message').textContent=m.coverage_percent===0?'The requested range has no published observations. No counts were manufactured.':'Some requested lane-time is unavailable. Incomplete groups have no total; passage summaries include complete groups only.';
 setDownloads();renderPage();
 }catch(e){$('#form-error').textContent=e.message;$('#form-error').hidden=false;dirty=true;setDownloads();}}
$('#query-form').addEventListener('submit',e=>{e.preventDefault();preview();});$('#query-form').addEventListener('input',markDirty);$('#query-form').addEventListener('change',markDirty);
$('#select-all').onclick=()=>{document.querySelectorAll('[name=site]').forEach(x=>x.checked=true);markDirty();};$('#select-none').onclick=()=>{document.querySelectorAll('[name=site]').forEach(x=>x.checked=false);markDirty();};
$('#sample-range').onclick=()=>{if(!archive)return;sampleRange();markDirty();preview();};$('#previous').onclick=()=>{if(page>0){page--;renderPage();}};$('#next').onclick=()=>{if((page+1)*pageSize<result.rows.length){page++;renderPage();}};
const filename=ext=>`PASADA_${result.metadata.source}_${result.metadata.requested_start_utc.slice(0,10)}.${ext}`;
$('#csv').onclick=()=>{if(!dirty&&result?.rows.length)download(filename('csv'),toCSV(result.rows),'text/csv;charset=utf-8');};$('#json').onclick=()=>{if(!dirty&&result?.rows.length)download(filename('json'),JSON.stringify(result,null,2),'application/json');};$('#metadata').onclick=()=>{if(!dirty&&result?.rows.length)download(filename('metadata.json'),JSON.stringify(result.metadata,null,2),'application/json');};$('#dictionary').onclick=()=>download('PASADA_data_dictionary.json',JSON.stringify(DICTIONARY,null,2),'application/json');
try{const response=await fetch('./archive.json');if(!response.ok)throw Error('Archive unavailable');archive=await response.json();$('#intersection-options').innerHTML=archive.intersections.map(j=>`<label class="site-option"><input type="checkbox" name="site" value="${esc(j.id)}" checked><span><strong>${esc(j.name)}</strong><small>${esc(j.id)} · ${j.lanes.length} counting lanes</small></span></label>`).join('');sampleRange();countSelected();$('#preview-button').disabled=false;preview();}catch(e){$('#result-title').textContent='Archive unavailable';$('#result-subtitle').textContent='Try reloading the page. Downloads stay disabled until an archive is available.';$('#intersection-options').textContent='Unable to load intersections.';}
